// Validates every publish body (POST /v1/public/events/) of a driver run against
// harness/contract/publish-event.schema.json (the publishEvent request schema of
// agentcat-server, generated by extract-schema.mjs) with ajv, formats included.
// The driver calls contractResult() after every run and records the result as
// `contract` (and the number of bodies checked as `contractChecked`) in report.json.
//
// usage: node harness/src/contract/validate.mjs [--allow-empty] <raw.json>
//   raw.json       a driver output file harness/out/<scenario>.<label>.<transport>.raw.json
//   --allow-empty  accept a run with no publish body (an untracked run); without it,
//                  zero bodies is a failure, so a wrong path or a wrong file never passes
// Exit 0: at least one publish body (or none, with --allow-empty) and every one is valid.
// Exit 1: no publish body, or one line per invalid body and error
// (INVALID publish seq=<n> id=<id> ...). Exit 2: bad arguments or an unreadable file.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { Ajv2020 } from "ajv/dist/2020.js";
import addFormats from "ajv-formats";

const HERE = dirname(fileURLToPath(import.meta.url));
export const SCHEMA_PATH = join(HERE, "..", "..", "contract", "publish-event.schema.json");
const PUBLISH_PATH = "/v1/public/events/";

/**
 * `schema` compiled with the settings every contract check uses: strict ajv (a keyword or format the
 * conversion left behind is a compile error), all errors, formats included. Throws ajv's error when the
 * schema does not compile. extract-schema.mjs compiles its output with this before it writes it.
 */
export function compileStrict(schema) {
  const ajv = new Ajv2020({ strict: true, allErrors: true });
  addFormats(ajv);
  return ajv.compile(schema);
}

let compiled;
/** The compiled committed schema. */
function validator() {
  if (!compiled) compiled = compileStrict(JSON.parse(readFileSync(SCHEMA_PATH, "utf8")));
  return compiled;
}

/**
 * Validates the publish bodies among recorded mock requests.
 * Returns {checked, invalid}: `invalid` holds one entry per failing body,
 * {seq, id, event_type, resource_name, errors: [{instancePath, keyword, message, params}]}.
 */
export function validateRequests(requests) {
  const validate = validator();
  const publishes = requests.filter((r) => r.method === "POST" && r.path === PUBLISH_PATH);
  const invalid = [];
  for (const request of publishes) {
    if (validate(request.body)) continue;
    const body = request.body !== null && typeof request.body === "object" ? request.body : {};
    invalid.push({
      seq: request.seq,
      id: body.id ?? null,
      event_type: body.event_type ?? null,
      resource_name: body.resource_name ?? null,
      errors: validate.errors.map(({ instancePath, keyword, message, params }) => ({ instancePath, keyword, message, params })),
    });
  }
  return { checked: publishes.length, invalid };
}

/** The `contract` value of a run that has no publish body although one is expected. */
export const NO_BODIES = "no publish bodies";

/**
 * The report.json contract fields: {checked, contract}. `contract` is "ok", the
 * invalid bodies, or NO_BODIES when no publish body was checked and `allowEmpty`
 * is false (the driver allows empty only when the scenario expects no publish).
 */
export function contractResult(requests, { allowEmpty = false } = {}) {
  const { checked, invalid } = validateRequests(requests);
  if (invalid.length > 0) return { checked, contract: invalid };
  if (checked === 0 && !allowEmpty) return { checked, contract: NO_BODIES };
  return { checked, contract: "ok" };
}

/** One line per error of each invalid body. */
export function formatInvalid(invalid) {
  return invalid.flatMap((entry) =>
    entry.errors.map(
      (e) =>
        `INVALID publish seq=${entry.seq} id=${entry.id} (${entry.event_type} ${entry.resource_name}): ` +
        `${e.instancePath || "/"} ${e.message}${e.keyword === "additionalProperties" ? ` (${e.params.additionalProperty})` : ""}`,
    ),
  );
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = process.argv.slice(2);
  const allowEmpty = args[0] === "--allow-empty";
  if (allowEmpty) args.shift();
  let requests;
  try {
    if (args.length !== 1 || args[0].startsWith("--")) {
      throw new Error("usage: node harness/src/contract/validate.mjs [--allow-empty] <raw.json>");
    }
    requests = JSON.parse(readFileSync(args[0], "utf8"));
    if (!Array.isArray(requests)) throw new Error(`${args[0]}: expected a JSON array of recorded requests`);
  } catch (err) {
    process.stderr.write(`validate: ${err.message}\n`);
    process.exit(2);
  }
  const { checked, contract } = contractResult(requests, { allowEmpty });
  if (contract === NO_BODIES) {
    process.stdout.write(
      `contract: 0 publish bodies; expected at least one (POST ${PUBLISH_PATH}; pass --allow-empty for a run that expects none)\n`,
    );
  } else if (contract !== "ok") {
    for (const line of formatInvalid(contract)) process.stdout.write(`${line}\n`);
    process.stdout.write(`contract: ${checked} publish bodies, ${contract.length} invalid\n`);
  } else {
    process.stdout.write(
      checked === 0 ? "contract: 0 publish bodies (allowed by --allow-empty)\n" : `contract: ${checked} publish bodies, all valid\n`,
    );
  }
  process.exitCode = contract === "ok" ? 0 : 1;
}
